import { type } from 'arktype';
import { IsInt, IsPositive, IsUUID, Matches, validateSync } from 'class-validator';
import { Schema } from 'effect';
import Joi from 'joi';
import * as S from 'sury';
import Type from 'typebox';
import type { TSchema } from 'typebox';
import { Compile } from 'typebox/compile';
import * as v from 'valibot';
import { z } from 'zod';

import { AnyString, Email, n, PositiveInteger, Uuid } from '../src/index.ts';
// Generated by `npm run bench:typia`; typia compiles its validators from types with ttsc.
import * as typia from './typia/dist/validators.js';

/**
 * One way a library checks a value at a boundary: it gets unknown input and answers with
 * something the calling code can use, a value or the reasons it was rejected.
 */
export type Check = (input: unknown) => unknown;

/**
 * The checks of one library, one per scenario; a library without a fitting API leaves one out.
 */
export interface Library {
  readonly name: string;
  /** Whether a result of this library's checks means the value was accepted. */
  readonly accepted: (result: unknown) => boolean;
  readonly sku?: Check;
  readonly uuid?: Check;
  readonly email?: Check;
  readonly positiveInteger?: Check;
  readonly uuidList?: Check;
}

const sku = /^SKU-\d{4}$/u;

const field = (result: unknown, key: string): unknown =>
  typeof result === 'object' && result !== null ? Reflect.get(result, key) : undefined;

class NominalSku extends AnyString.subtype('BenchSku', sku) {}

const nominalUuids = n.of(Uuid).array();

const ownTry =
  (run: (input: unknown) => unknown): Check =>
  (input) => {
    try {
      return run(input);
    } catch (error) {
      return error;
    }
  };

const classValidatorOf = (...decorators: PropertyDecorator[]): Check => {
  class Dto {
    public value: unknown;
  }

  for (const decorate of decorators) {
    decorate(Dto.prototype, 'value');
  }

  return (input) => {
    const dto = new Dto();

    dto.value = input;

    return validateSync(dto);
  };
};

const toZod =
  <Out>(schema: z.ZodType<Out>): Check =>
  (input) =>
    schema.safeParse(input);

const toValibot =
  (schema: v.GenericSchema): Check =>
  (input) =>
    v.safeParse(schema, input);

const effectOf = (schema: Schema.Codec<unknown>): Check => {
  const decode = Schema.decodeUnknownResult(schema);

  return (input) => decode(input);
};

class TypeBoxErrors {
  public readonly errors: readonly unknown[];

  public constructor(errors: readonly unknown[]) {
    this.errors = errors;
  }
}

const typeboxOf = (schema: TSchema): Check => {
  const validator = Compile(schema);

  return (input) =>
    validator.Check(input) ? input : new TypeBoxErrors([...validator.Errors(input)]);
};

const joiOf =
  (schema: Joi.Schema): Check =>
  (input) =>
    schema.validate(input);

const suryOf = (schema: S.Schema): Check => ownTry((input) => S.parseOrThrow(input, schema));

export const libraries: readonly Library[] = [
  {
    name: 'nominal-types',
    accepted: (result) => field(result, 'ok') === true,
    sku: (input) => NominalSku.parse(input),
    uuid: (input) => Uuid.parse(input),
    email: (input) => Email.parse(input),
    positiveInteger: (input) => PositiveInteger.parse(input),
    uuidList: (input) => nominalUuids.parse(input),
  },
  {
    name: 'typia',
    accepted: (result) => result !== undefined && field(result, 'success') !== false,
    sku: typia.validateSku,
    uuid: (input) => (typia.isUuid(input) ? input : undefined),
    email: (input) => (typia.isEmail(input) ? input : undefined),
    positiveInteger: (input) => (typia.isPositiveInteger(input) ? input : undefined),
    uuidList: (input) => (typia.isUuidList(input) ? input : undefined),
  },
  {
    name: 'arktype',
    accepted: (result) => !(result instanceof type.errors),
    sku: type(sku),
    uuid: type('string.uuid'),
    email: type('string.email'),
    positiveInteger: type('number.integer > 0'),
    uuidList: type('string.uuid[]'),
  },
  {
    name: 'zod',
    accepted: (result) => field(result, 'success') === true,
    sku: toZod(z.string().regex(sku)),
    uuid: toZod(z.uuid()),
    email: toZod(z.email()),
    positiveInteger: toZod(z.number().int().positive()),
    uuidList: toZod(z.array(z.uuid())),
  },
  {
    name: 'valibot',
    accepted: (result) => field(result, 'success') === true,
    sku: toValibot(v.pipe(v.string(), v.regex(sku))),
    uuid: toValibot(v.pipe(v.string(), v.uuid())),
    email: toValibot(v.pipe(v.string(), v.email())),
    positiveInteger: toValibot(v.pipe(v.number(), v.integer(), v.minValue(1))),
    uuidList: toValibot(v.array(v.pipe(v.string(), v.uuid()))),
  },
  {
    name: 'sury',
    accepted: (result) => !(result instanceof Error),
    sku: suryOf(S.pattern(S.string, sku)),
    uuid: suryOf(S.uuid),
    email: suryOf(S.email),
    positiveInteger: suryOf(S.gt(S.integer, 0)),
    uuidList: suryOf(S.array(S.uuid)),
  },
  {
    name: 'effect',
    accepted: (result) => field(result, '_tag') === 'Success',
    sku: effectOf(Schema.String.check(Schema.isPattern(sku))),
    uuid: effectOf(Schema.String.check(Schema.isUUID())),
    positiveInteger: effectOf(Schema.Number.check(Schema.isInt(), Schema.isGreaterThan(0))),
    uuidList: effectOf(Schema.Array(Schema.String.check(Schema.isUUID()))),
  },
  {
    name: 'typebox',
    accepted: (result) => !(result instanceof TypeBoxErrors),
    sku: typeboxOf(Type.String({ pattern: sku.source })),
    uuid: typeboxOf(Type.String({ format: 'uuid' })),
    email: typeboxOf(Type.String({ format: 'email' })),
    positiveInteger: typeboxOf(Type.Integer({ minimum: 1 })),
    uuidList: typeboxOf(Type.Array(Type.String({ format: 'uuid' }))),
  },
  {
    name: 'joi',
    accepted: (result) => field(result, 'error') === undefined,
    sku: joiOf(Joi.string().pattern(sku)),
    uuid: joiOf(Joi.string().uuid()),
    email: joiOf(Joi.string().email()),
    positiveInteger: joiOf(Joi.number().integer().positive()),
    uuidList: joiOf(Joi.array().items(Joi.string().uuid())),
  },
  {
    name: 'class-validator',
    accepted: (result) => Array.isArray(result) && result.length === 0,
    sku: classValidatorOf(Matches(sku)),
    uuid: classValidatorOf(IsUUID('all')),
    positiveInteger: classValidatorOf(IsInt(), IsPositive()),
  },
];
